def transform(grid):
    g=[row[:] for row in grid]
    line=grid[0][0]
    mark=({v for row in grid for v in row}-{line,grid[1][1],grid[2][2]}).pop()
    seed={(r//4,c//4) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c]==mark}
    height=max(r for r,c in seed)-min(r for r,c in seed)+1
    side=max(3,2*height)
    R1=max(r for r,c in seed); R0=R1-side+1
    C0=min(c for r,c in seed); C1=C0+side-1
    R,C=next(iter(seed))
    motif=[[grid[R*4+1+dr][C*4+1+dc] for dc in range(3)] for dr in range(3)]
    for R in range(R0,R1+1):
        for C in range(C0,C1+1):
            if (R,C) not in seed and (C==C1 or ((R<min(r for r,c in seed) or R>R1) and (C-C0-(1-side%2))%2==0)):
                for dr in range(3):
                    for dc in range(3):g[R*4+1+dr][C*4+1+dc]=motif[dr][dc]
    return g

